        Assert.notNull(headers, "Headers must not be null");
        this.completionsPath = completionsPath;
        this.betaPrefixPath = betaPrefixPath;
        Consumer<HttpHeaders> finalHeaders = h -> {
            h.setBearerAuth(apiKey.getValue());
            h.setContentType(MediaType.APPLICATION_JSON);
            h.addAll(HttpHeaders.readOnlyHttpHeaders(headers));
        };
        this.restClient = restClientBuilder.clone().baseUrl(baseUrl).defaultHeaders(finalHeaders).defaultStatusHandler(responseErrorHandler).build();
        this.webClient = webClientBuilder.clone().baseUrl(baseUrl).defaultHeaders(finalHeaders).build();
    }

    /**
     * Create a new chat completion api.
     * @param completionsPath the path to the chat completions endpoint.
     * @param betaPrefixPath the prefix path to the beta feature endpoint.
     * @param restClient RestClient instance.
     * @param webClient WebClient instance.
     */
    public DeepSeekApi(String completionsPath, String betaPrefixPath, RestClient restClient, WebClient webClient) {
        Assert.hasText(completionsPath, "Completions Path must not be null");
        Assert.hasText(betaPrefixPath, "Beta feature path must not be null");
        Assert.notNull(restClient, "RestClient must not be null");
        Assert.notNull(webClient, "WebClient must not be null");
        this.completionsPath = completionsPath;
        this.betaPrefixPath = betaPrefixPath;
        this.restClient = restClient;
        this.webClient = webClient;
    }

    /**
     * Creates a model response for the given chat conversation.
     * @param chatRequest The chat completion request.
     * @return Entity response with {@link ChatCompletion} as a body and HTTP status code
     * and headers.
     */
    public ResponseEntity<ChatCompletion> chatCompletionEntity(ChatCompletionRequest chatRequest) {
        Assert.notNull(chatRequest, "The request body can not be null.");
        Assert.isTrue(Boolean.FALSE.equals(chatRequest.stream()), "Request must set the stream property to false.");
        return this.restClient.post().uri(this.getEndpoint(chatRequest)).body(chatRequest).retrieve().toEntity(ChatCompletion.class);
    }

    /**
     * Creates a streaming chat response for the given chat conversation.
     * @param chatRequest The chat completion request. Must have the stream property set
     * to true.
     * @return Returns a {@link Flux} stream from chat completion chunks.
     */
    public Flux<ChatCompletionChunk> chatCompletionStream(ChatCompletionRequest chatRequest) {
        return chatCompletionStream(chatRequest, new HttpHeaders());
    }

    /**
     * Creates a streaming chat response for the given chat conversation.
     * @param chatRequest The chat completion request. Must have the stream property set
     * to true.
     * @param additionalHttpHeader Optional, additional HTTP headers to be added to the
     * request.
     * @return Returns a {@link Flux} stream from chat completion chunks.
     */
    public Flux<ChatCompletionChunk> chatCompletionStream(ChatCompletionRequest chatRequest, HttpHeaders additionalHttpHeader) {
        Assert.notNull(chatRequest, "The request body can not be null.");
        Assert.isTrue(Boolean.TRUE.equals(chatRequest.stream()), "Request must set the stream property to true.");
        AtomicBoolean isInsideTool = new AtomicBoolean(false);
        return this.webClient.post().uri(this.getEndpoint(chatRequest)).headers(headers -> headers.addAll(HttpHeaders.readOnlyHttpHeaders(additionalHttpHeader))).body(Mono.just(chatRequest), ChatCompletionRequest.class).retrieve().bodyToFlux(String.class).// cancels the flux stream after the "[DONE]" is received.
        takeUntil(SSE_DONE_PREDICATE).// filters out the "[DONE]" message.
        filter(SSE_DONE_PREDICATE.negate()).map(content -> ModelOptionsUtils.jsonToObject(content, ChatCompletionChunk.class)).// Detect is the chunk is part of a streaming function call.
        map(chunk -> {
            if (this.chunkMerger.isStreamingToolFunctionCall(chunk)) {
                isInsideTool.set(true);
            }
            return chunk;
        }).// Group all chunks belonging to the same function call.
        // Flux<ChatCompletionChunk> -> Flux<Flux<ChatCompletionChunk>>
        windowUntil(chunk -> {
            if (isInsideTool.get() && this.chunkMerger.isStreamingToolFunctionCallFinish(chunk)) {
                isInsideTool.set(false);
                return true;
            }
            return !isInsideTool.get();
        }).// Merging the window chunks into a single chunk.
        // Reduce the inner Flux<ChatCompletionChunk> window into a single
        // Mono<ChatCompletionChunk>,
        // Flux<Flux<ChatCompletionChunk>> -> Flux<Mono<ChatCompletionChunk>>
        concatMapIterable(window -> {
            Mono<ChatCompletionChunk> monoChunk = window.reduce(this.chunkMerger::merge);
            return List.of(monoChunk);
        }).// Flux<Mono<ChatCompletionChunk>> -> Flux<ChatCompletionChunk>
        flatMap(mono -> mono);
    }

    private String getEndpoint(ChatCompletionRequest request) {
        boolean isPrefix = request.messages.stream().map(ChatCompletionMessage::prefix).filter(Objects::nonNull).anyMatch(prefix -> prefix);
        String endpointPrefix = isPrefix ? this.betaPrefixPath : "";
        return endpointPrefix + this.completionsPath;
    }

