/**
 * Integration tests for Google GenAI Chat autoconfiguration.
 *
 * This test can run in two modes: 1. With GOOGLE_API_KEY environment variable (Gemini
 * Developer API mode) 2. With GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_LOCATION environment
 * variables (Vertex AI mode)
 */
public class GoogleGenAiChatAutoConfigurationIT {

    private static final Log logger = LogFactory.getLog(GoogleGenAiChatAutoConfigurationIT.class);

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(GoogleGenAiChatAutoConfiguration.class, SpringAiRetryAutoConfiguration.class, ToolCallingAutoConfiguration.class));

    @Test
    @EnabledIfEnvironmentVariable(named = "GOOGLE_API_KEY", matches = ".+")
    void shouldNotFailOnAmbiguousConfigurationButPrioritizeApiKey() {
        this.contextRunner.withPropertyValues("spring.ai.google.genai.api-key=" + System.getenv("GOOGLE_API_KEY"), "spring.ai.google.genai.project-id=test-project", "spring.ai.google.genai.location=us-central1").run(context -> assertThat(context).hasSingleBean(Client.class));
    }

    @Test
    void shouldFailWhenVertexAiEnabledButConfigMissing() {
        this.contextRunner.withPropertyValues("spring.ai.google.genai.vertex-ai=true").// Explicitly enabled but no project/location
        run(context -> {
            assertThat(context).hasFailed();
            assertThat(context.getStartupFailure()).hasRootCauseInstanceOf(IllegalStateException.class).hasMessageContaining("Vertex AI mode requires both 'project-id' and 'location' to be configured.");
        });
    }

    @Test
    @EnabledIfEnvironmentVariable(named = "GOOGLE_CLOUD_PROJECT", matches = ".+")
    @EnabledIfEnvironmentVariable(named = "GOOGLE_CLOUD_LOCATION", matches = ".+")
    void shouldConfigureVertexAiSuccessfully() {
        this.contextRunner.withPropertyValues("spring.ai.google.genai.project-id=" + System.getenv("GOOGLE_CLOUD_PROJECT"), "spring.ai.google.genai.location=" + System.getenv("GOOGLE_CLOUD_LOCATION")).run(context -> assertThat(context).hasSingleBean(Client.class));
    }

    @Test
    @EnabledIfEnvironmentVariable(named = "GOOGLE_API_KEY", matches = ".+")
    void shouldConfigureApiKeySuccessfully() {
        this.contextRunner.withPropertyValues("spring.ai.google.genai.api-key=" + System.getenv("GOOGLE_API_KEY")).run(context -> assertThat(context).hasSingleBean(Client.class));
    }

    @Test
