/**
 * @author Christian Tzolov
 * @author Alexandros Pappas
 * @author Vadzim Shurmialiou
 * @author Craig Walls
 */
public class AsyncMcpToolProvider extends AbstractMcpToolProvider {

    private static final Logger logger = LoggerFactory.getLogger(AsyncMcpToolProvider.class);

    /**
     * Create a new SyncMcpToolProvider.
     * @param toolObjects the objects containing methods annotated with {@link McpTool}
     */
    public AsyncMcpToolProvider(List<Object> toolObjects) {
        super(toolObjects);
    }

    /**
     * Get the tool handler.
     * @return the tool handler
     * @throws IllegalStateException if no tool methods are found or if multiple tool
     * methods are found
     */
    public List<AsyncToolSpecification> getToolSpecifications() {
        List<AsyncToolSpecification> toolSpecs = this.toolObjects.stream().map(toolObject -> Stream.of(this.doGetClassMethods(toolObject)).filter(method -> method.isAnnotationPresent(McpTool.class)).filter(McpPredicates.filterNonReactiveReturnTypeMethod()).sorted(Comparator.comparing(Method::getName)).map(mcpToolMethod -> {
            var toolJavaAnnotation = this.doGetMcpToolAnnotation(mcpToolMethod);
            String toolName = Utils.hasText(toolJavaAnnotation.name()) ? toolJavaAnnotation.name() : mcpToolMethod.getName();
            String toolDescription = toolJavaAnnotation.description();
            String inputSchema = McpJsonSchemaGenerator.generateForMethodInput(mcpToolMethod);
            var meta = MetaUtils.getMeta(toolJavaAnnotation.metaProvider());
            var toolBuilder = McpSchema.Tool.builder().name(toolName).description(toolDescription).inputSchema(this.getJsonMapper(), inputSchema).meta(meta);
            var title = toolJavaAnnotation.title();
            // Tool annotations
            if (toolJavaAnnotation.annotations() != null) {
                var toolAnnotations = toolJavaAnnotation.annotations();
                toolBuilder.annotations(new McpSchema.ToolAnnotations(toolAnnotations.title(), toolAnnotations.readOnlyHint(), toolAnnotations.destructiveHint(), toolAnnotations.idempotentHint(), toolAnnotations.openWorldHint(), null));
                // If not provided, the name should be used for display (except
                // for Tool, where annotations.title should be given precedence
                // over using name, if present).
                if (!Utils.hasText(title)) {
                    title = toolAnnotations.title();
                }
            }
            // If not provided, the name should be used for display (except
            // for Tool, where annotations.title should be given precedence
            // over using name, if present).
            if (!Utils.hasText(title)) {
                title = toolName;
            }
            toolBuilder.title(title);
            // Generate Output Schema from the method return type.
            // Output schema is not generated for primitive types, void,
            // CallToolResult, simple value types (String, etc.)
            // or if generateOutputSchema attribute is set to false.
            if (toolJavaAnnotation.generateOutputSchema() && !ReactiveUtils.isReactiveReturnTypeOfVoid(mcpToolMethod) && !ReactiveUtils.isReactiveReturnTypeOfCallToolResult(mcpToolMethod)) {
                ReactiveUtils.getReactiveReturnTypeArgument(mcpToolMethod).ifPresent(typeArgument -> {
                    Class<?> methodReturnType = typeArgument instanceof Class<?> ? (Class<?>) typeArgument : null;
                    if (!ClassUtils.isPrimitiveOrWrapper(methodReturnType) && !ClassUtils.isSimpleValueType(methodReturnType)) {
                        toolBuilder.outputSchema(this.getJsonMapper(), McpJsonSchemaGenerator.generateFromClass((Class<?>) typeArgument));
                    }
                });
            }
            var tool = toolBuilder.build();
            ReturnMode returnMode = tool.outputSchema() != null ? ReturnMode.STRUCTURED : ReactiveUtils.isReactiveReturnTypeOfVoid(mcpToolMethod) ? ReturnMode.VOID : ReturnMode.TEXT;
            BiFunction<McpAsyncServerExchange, CallToolRequest, Mono<CallToolResult>> methodCallback = new AsyncMcpToolMethodCallback(returnMode, mcpToolMethod, toolObject, this.doGetToolCallException());
            AsyncToolSpecification toolSpec = AsyncToolSpecification.builder().tool(tool).callHandler(methodCallback).build();
            return toolSpec;
        }).toList()).flatMap(List::stream).toList();
        if (toolSpecs.isEmpty()) {
            logger.warn("No tool methods found in the provided tool objects: {}", this.toolObjects);
        }
        return toolSpecs;
    }
}

