 * Integration test to reproduce the issue where MCP tools with no parameters (incomplete
 * schemas) fail to create valid tool definitions.
 *
 * @author Ilayaperumal Gopinathan
 */
class McpToolCallbackParameterlessToolIT {

    private final ApplicationContextRunner syncServerContextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.mcp.server.protocol=STREAMABLE", "spring.ai.mcp.server.type=SYNC").withConfiguration(AutoConfigurations.of(McpServerAutoConfiguration.class, McpServerJsonMapperAutoConfiguration.class, ToolCallbackConverterAutoConfiguration.class, McpServerStreamableHttpWebFluxAutoConfiguration.class, McpServerAnnotationScannerAutoConfiguration.class, McpServerSpecificationFactoryAutoConfiguration.class));

