    }

    public static class TestMcpServerConfiguration {

        @Bean
        public List<McpServerFeatures.SyncToolSpecification> myTools() {
            // Tool 1
            McpServerFeatures.SyncToolSpecification tool1 = McpServerFeatures.SyncToolSpecification.builder().tool(Tool.builder().name("tool1").description("tool1 description").inputSchema(jsonMapper, """
                {
                	"": "http://json-schema.org/draft-07/schema#",
                	"type": "object",
                	"properties": {}
                }
                """).build()).callHandler((exchange, request) -> {
                var progressToken = request.progressToken();
                exchange.progressNotification(new ProgressNotification(progressToken, 0.0, 1.0, "tool call start"));
                // call client ping
                exchange.ping();
                // call elicitation
                var elicitationRequest = McpSchema.ElicitRequest.builder().message("Test message").requestedSchema(Map.of("type", "object", "properties", Map.of("message", Map.of("type", "string")))).build();
                ElicitResult elicitationResult = exchange.createElicitation(elicitationRequest);
                exchange.progressNotification(new ProgressNotification(progressToken, 0.50, 1.0, "elicitation completed"));
                // call sampling
                var createMessageRequest = McpSchema.CreateMessageRequest.builder().messages(List.of(new McpSchema.SamplingMessage(McpSchema.Role.USER, new McpSchema.TextContent("Test Sampling Message")))).modelPreferences(ModelPreferences.builder().hints(List.of(ModelHint.of("OpenAi"), ModelHint.of("Ollama"))).costPriority(1.0).speedPriority(1.0).intelligencePriority(1.0).build()).build();
                CreateMessageResult samplingResponse = exchange.createMessage(createMessageRequest);
                exchange.progressNotification(new ProgressNotification(progressToken, 1.0, 1.0, "sampling completed"));
                return McpSchema.CallToolResult.builder().content(List.of(new McpSchema.TextContent("CALL RESPONSE: " + samplingResponse.toString() + ", " + elicitationResult.toString()))).build();
            }).build();
            // Tool 2
            // Create a tool with output schema
            Map<String, Object> outputSchema = Map.of("type", "object", "properties", Map.of("result", Map.of("type", "number"), "operation", Map.of("type", "string"), "timestamp", Map.of("type", "string")), "required", List.of("result", "operation"));
            Tool calculatorTool = Tool.builder().name("calculator").description("Performs mathematical calculations").outputSchema(outputSchema).build();
            McpServerFeatures.SyncToolSpecification tool2 = McpServerFeatures.SyncToolSpecification.builder().tool(calculatorTool).callHandler((exchange, request) -> {
                String expression = (String) request.arguments().getOrDefault("expression", "2 + 3");
                double result = this.evaluateExpression(expression);
                return CallToolResult.builder().structuredContent(Map.of("result", result, "operation", expression, "timestamp", "2024-01-01T10:00:00Z")).build();
            }).build();
            return List.of(tool1, tool2);
