            final AtomicReference<LoggingMessageNotification> loggingNotificationRef = new AtomicReference<>();

            final CountDownLatch progressLatch = new CountDownLatch(3);

            final List<McpSchema.ProgressNotification> progressNotifications = new CopyOnWriteArrayList<>();
        }

        public static class McpClientHandlers {

            private static final Logger logger = LoggerFactory.getLogger(McpClientHandlers.class);

            private TestContext testContext;

            private final ObjectProvider<ChatClient.Builder> chatClientBuilderProvider;

            private AtomicReference<ChatClient> chatClientRef = new AtomicReference<>();

            private ChatClient chatClient() {
                if (this.chatClientRef.get() == null) {
                    this.chatClientRef.compareAndSet(null, this.chatClientBuilderProvider.getIfAvailable().build());
                }
                return this.chatClientRef.get();
            }

            public McpClientHandlers(TestContext testContext, ObjectProvider<ChatClient.Builder> chatClientBuilderProvider) {
                this.testContext = testContext;
                this.chatClientBuilderProvider = chatClientBuilderProvider;
            }

            @McpProgress(clients = "server1")
            public void progressHandler(ProgressNotification progressNotification) {
                logger.info("MCP PROGRESS: [{}] progress: {} total: {} message: {}", progressNotification.progressToken(), progressNotification.progress(), progressNotification.total(), progressNotification.message());
                this.testContext.progressNotifications.add(progressNotification);
                this.testContext.progressLatch.countDown();
            }

            @McpLogging(clients = "server1")
