@EnabledIfEnvironmentVariable(named = "ANTHROPIC_API_KEY", matches = ".+")
public class StreamableMcpAnnotationsWithLLMIT {

    private final ApplicationContextRunner serverContextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.mcp.server.protocol=STREAMABLE").withConfiguration(AutoConfigurations.of(McpServerAutoConfiguration.class, McpServerJsonMapperAutoConfiguration.class, ToolCallbackConverterAutoConfiguration.class, McpServerStreamableHttpWebFluxAutoConfiguration.class, McpServerAnnotationScannerAutoConfiguration.class, McpServerSpecificationFactoryAutoConfiguration.class));

    private final ApplicationContextRunner clientApplicationContext = new ApplicationContextRunner().withPropertyValues("spring.ai.anthropic.apiKey=" + System.getenv("ANTHROPIC_API_KEY")).withConfiguration(anthropicAutoConfig(McpToolCallbackAutoConfiguration.class, McpClientAutoConfiguration.class, StreamableHttpWebFluxTransportAutoConfiguration.class, McpClientAnnotationScannerAutoConfiguration.class, AnthropicChatAutoConfiguration.class, ChatClientAutoConfiguration.class));

    private static AutoConfigurations anthropicAutoConfig(Class<?>... additional) {
        Class<?>[] dependencies = { ToolCallingAutoConfiguration.class, RestClientAutoConfiguration.class, WebClientAutoConfiguration.class };
        Class<?>[] all = Stream.concat(Arrays.stream(dependencies), Arrays.stream(additional)).toArray(Class<?>[]::new);
        return AutoConfigurations.of(all);
    }

    private static AtomicInteger toolCounter = new AtomicInteger(0);

    @Test
    void clientServerCapabilities() {
        int serverPort = TestSocketUtils.findAvailableTcpPort();
        this.serverContextRunner.withUserConfiguration(TestMcpServerConfiguration.class).// @formatter:off
        withPropertyValues("spring.ai.mcp.server.name=test-mcp-server", "spring.ai.mcp.server.version=1.0.0", "spring.ai.mcp.server.streamable-http.keep-alive-interval=1s", // @formatter:on
        "spring.ai.mcp.server.streamable-http.mcp-endpoint=/mcp").run(serverContext -> {
            // Verify all required beans are present
            assertThat(serverContext).hasSingleBean(WebFluxStreamableServerTransportProvider.class);
            assertThat(serverContext).hasSingleBean(RouterFunction.class);
            assertThat(serverContext).hasSingleBean(McpSyncServer.class);
            // Verify server properties are configured correctly
            McpServerProperties properties = serverContext.getBean(McpServerProperties.class);
            assertThat(properties.getName()).isEqualTo("test-mcp-server");
            assertThat(properties.getVersion()).isEqualTo("1.0.0");
            McpServerStreamableHttpProperties streamableHttpProperties = serverContext.getBean(McpServerStreamableHttpProperties.class);
            assertThat(streamableHttpProperties.getMcpEndpoint()).isEqualTo("/mcp");
            assertThat(streamableHttpProperties.getKeepAliveInterval()).isEqualTo(Duration.ofSeconds(1));
            var httpServer = startHttpServer(serverContext, serverPort);
            this.clientApplicationContext.withUserConfiguration(TestMcpClientConfiguration.class).withUserConfiguration(TestMcpClientHandlers.class).// @formatter:off
            withPropertyValues("spring.ai.mcp.client.streamable-http.connections.server1.url=http://localhost:" + serverPort, // @formatter:on
            "spring.ai.mcp.client.initialized=false").run(clientContext -> {
                ChatClient.Builder builder = clientContext.getBean(ChatClient.Builder.class);
                ToolCallbackProvider tcp = clientContext.getBean(ToolCallbackProvider.class);
                assertThat(builder).isNotNull();
                ChatClient chatClient = builder.defaultToolCallbacks(tcp).defaultToolContext(Map.of("progressToken", "test-progress-token")).build();
                String cResponse = chatClient.prompt().user("What is the weather in Amsterdam right now").call().content();
                assertThat(cResponse).isNotEmpty();
                assertThat(cResponse).contains("22");
                assertThat(toolCounter.get()).isEqualTo(1);
                // PROGRESS
                TestMcpClientConfiguration.TestContext testContext = clientContext.getBean(TestMcpClientConfiguration.TestContext.class);
                assertThat(testContext.progressLatch.await(5, TimeUnit.SECONDS)).as("Should receive progress notifications in reasonable time").isTrue();
                assertThat(testContext.progressNotifications).hasSize(3);
                Map<String, McpSchema.ProgressNotification> notificationMap = testContext.progressNotifications.stream().collect(Collectors.toMap(n -> n.message(), n -> n));
                // First notification should be 0.0/1.0 progress
                assertThat(notificationMap.get("tool call start").progressToken()).isEqualTo("test-progress-token");
                assertThat(notificationMap.get("tool call start").progress()).isEqualTo(0.0);
                assertThat(notificationMap.get("tool call start").total()).isEqualTo(1.0);
                assertThat(notificationMap.get("tool call start").message()).isEqualTo("tool call start");
                // Second notification should be 1.0/1.0 progress
                assertThat(notificationMap.get("elicitation completed").progressToken()).isEqualTo("test-progress-token");
                assertThat(notificationMap.get("elicitation completed").progress()).isEqualTo(0.5);
                assertThat(notificationMap.get("elicitation completed").total()).isEqualTo(1.0);
                assertThat(notificationMap.get("elicitation completed").message()).isEqualTo("elicitation completed");
                // Third notification should be 0.5/1.0 progress
                assertThat(notificationMap.get("sampling completed").progressToken()).isEqualTo("test-progress-token");
                assertThat(notificationMap.get("sampling completed").progress()).isEqualTo(1.0);
                assertThat(notificationMap.get("sampling completed").total()).isEqualTo(1.0);
                assertThat(notificationMap.get("sampling completed").message()).isEqualTo("sampling completed");
            });
            stopHttpServer(httpServer);
        });
    }

    // Helper methods to start and stop the HTTP server
    private static DisposableServer startHttpServer(ApplicationContext serverContext, int port) {
        WebFluxStreamableServerTransportProvider mcpStreamableServerTransport = serverContext.getBean(WebFluxStreamableServerTransportProvider.class);
        HttpHandler httpHandler = RouterFunctions.toHttpHandler(mcpStreamableServerTransport.getRouterFunction());
        ReactorHttpHandlerAdapter adapter = new ReactorHttpHandlerAdapter(httpHandler);
        return HttpServer.create().port(port).handle(adapter).bindNow();
    }

    private static void stopHttpServer(DisposableServer server) {
        if (server != null) {
            server.disposeNow();
        }
    }

