                CreateMessageResult samplingResponse = ctx.sample(s -> s.message("Test Sampling Message").modelPreferences(pref -> pref.modelHints("OpenAi", "Ollama").costPriority(1.0).speedPriority(1.0).intelligencePriority(1.0)));
                ctx.progress(p -> p.progress(1.0).total(1.0).message("sampling completed"));
                ctx.info("Tool1 Done!");
                return "Weahter is 22C with rain " + samplingResponse.toString() + ", " + elicitationResult.toString();
