                return CreateMessageResult.builder().content(new McpSchema.TextContent("Response " + userPrompt + " with model hint " + modelHint)).build();
            }

            @McpElicitation(clients = "server1")
            public ElicitResult elicitationHandler(McpSchema.ElicitRequest request) {
                logger.info("MCP ELICITATION: {}", request);
                return new ElicitResult(ElicitResult.Action.ACCEPT, Map.of("message", request.message()));
