        withPropertyValues("spring.ai.mcp.server.name=test-mcp-server", "spring.ai.mcp.server.version=1.0.0", "spring.ai.mcp.server.streamable-http.keep-alive-interval=1s", // @formatter:on
        "spring.ai.mcp.server.streamable-http.mcp-endpoint=/mcp").run(serverContext -> {
            // Verify all required beans are present
