            public CallToolResult calculator(@McpToolParam String expression, McpMeta meta) {
                double result = evaluateExpression(expression);
                return CallToolResult.builder().structuredContent(Map.of("result", result, "operation", expression, "timestamp", "2024-01-01T10:00:00Z")).meta(Map.of("meta1Response", meta.get("meta1"))).build();
