                try {
                    var systemInfo = Map.of("os", System.getProperty("os.name"), "os_version", System.getProperty("os.version"), "java_version", System.getProperty("java.version"));
                    String jsonContent = JsonMapper.shared().writeValueAsString(systemInfo);
                    return new ReadResourceResult(List.of(new McpSchema.TextResourceContents(request.uri(), "application/json", jsonContent)));
