    public static class TestMcpClientConfiguration {

        @Bean
        public TestContext testContext() {
            return new TestContext();
        }

        @Bean
        public McpClientHandlers mcpClientHandlers(TestContext testContext, ObjectProvider<ChatClient.Builder> chatClientBuilderProvider) {
            return new McpClientHandlers(testContext, chatClientBuilderProvider);
        }

        public static class TestContext {

            final AtomicReference<LoggingMessageNotification> loggingNotificationRef = new AtomicReference<>();

            final CountDownLatch progressLatch = new CountDownLatch(3);

            final List<McpSchema.ProgressNotification> progressNotifications = new CopyOnWriteArrayList<>();
        }

        public static class McpClientHandlers {

            private static final Logger logger = LoggerFactory.getLogger(McpClientHandlers.class);

            private TestContext testContext;

            private final ObjectProvider<ChatClient.Builder> chatClientBuilderProvider;

            private AtomicReference<ChatClient> chatClientRef = new AtomicReference<>();

            private ChatClient chatClient() {
                if (this.chatClientRef.get() == null) {
                    this.chatClientRef.compareAndSet(null, this.chatClientBuilderProvider.getIfAvailable().build());
                }
                return this.chatClientRef.get();
            }

            public McpClientHandlers(TestContext testContext, ObjectProvider<ChatClient.Builder> chatClientBuilderProvider) {
                this.testContext = testContext;
                this.chatClientBuilderProvider = chatClientBuilderProvider;
            }

            @McpProgress(clients = "server1")
            public void progressHandler(ProgressNotification progressNotification) {
                logger.info("MCP PROGRESS: [{}] progress: {} total: {} message: {}", progressNotification.progressToken(), progressNotification.progress(), progressNotification.total(), progressNotification.message());
                this.testContext.progressNotifications.add(progressNotification);
                this.testContext.progressLatch.countDown();
            }

            @McpLogging(clients = "server1")
            public void loggingHandler(LoggingMessageNotification loggingMessage) {
                this.testContext.loggingNotificationRef.set(loggingMessage);
                logger.info("MCP LOGGING: [{}] {}", loggingMessage.level(), loggingMessage.data());
            }

            @McpSampling(clients = "server1")
            public CreateMessageResult samplingHandler(CreateMessageRequest llmRequest) {
                logger.info("MCP SAMPLING: {}", llmRequest);
                String userPrompt = ((McpSchema.TextContent) llmRequest.messages().get(0).content()).text();
                String modelHint = llmRequest.modelPreferences().hints().get(0).name();
                // String joke =
                // this.chatClientBuilderProvider.getIfAvailable().build().prompt("Tell me
                // a joke").call().content();
                String joke = this.chatClient().prompt("Tell me a joke").call().content();
                logger.info("Received joke from chat client: {}", joke);
                return CreateMessageResult.builder().content(new McpSchema.TextContent("Response " + userPrompt + " with model hint " + modelHint)).build();
            }

            @McpElicitation(clients = "server1")
            public ElicitResult elicitationHandler(McpSchema.ElicitRequest request) {
                logger.info("MCP ELICITATION: {}", request);
                return new ElicitResult(ElicitResult.Action.ACCEPT, Map.of("message", request.message()));
            }
        }
    }
}

