                    };
                }
            };
        }
    }

    @AutoConfiguration
    static class CustomAwsRegionProviderAutoConfiguration {

        @Bean
        @ConditionalOnMissingBean
        public AwsRegionProvider regionProvider() {
            return new AwsRegionProvider() {

                @Override
                public Region getRegion() {
                    return Region.AWS_GLOBAL;
                }
            };
        }
    }
