    void roleTest(String modelName) {
        UserMessage userMessage = new UserMessage("Tell me about 3 famous pirates from the Golden Age of Piracy and why they did.");
        SystemPromptTemplate systemPromptTemplate = new SystemPromptTemplate(this.systemResource);
        Message systemMessage = systemPromptTemplate.createMessage(Map.of("name", "Bob", "voice", "pirate"));
        Prompt prompt = new Prompt(List.of(userMessage, systemMessage), BedrockChatOptions.builder().model(modelName).build());
        ChatResponse response = this.chatModel.call(prompt);
        assertThat(response.getResults()).hasSize(1);
        assertThat(response.getMetadata().getUsage().getCompletionTokens()).isGreaterThan(0);
        assertThat(response.getMetadata().getUsage().getPromptTokens()).isGreaterThan(0);
        assertThat(response.getMetadata().getUsage().getTotalTokens()).isEqualTo(response.getMetadata().getUsage().getPromptTokens() + response.getMetadata().getUsage().getCompletionTokens());
        Generation generation = response.getResults().get(0);
