@AutoConfiguration
@ConditionalOnClass({ Client.class, GoogleGenAiChatModel.class })
@ConditionalOnProperty(name = SpringAIModelProperties.CHAT_MODEL, havingValue = SpringAIModels.GOOGLE_GEN_AI, matchIfMissing = true)
@EnableConfigurationProperties({ GoogleGenAiChatProperties.class, GoogleGenAiConnectionProperties.class })
public class GoogleGenAiChatAutoConfiguration {

    private static final Log logger = LogFactory.getLog(GoogleGenAiChatAutoConfiguration.class);

    @Bean
    @ConditionalOnMissingBean
    public Client googleGenAiClient(GoogleGenAiConnectionProperties properties) throws IOException {
        Client.Builder builder = Client.builder();
        boolean hasApiKey = StringUtils.hasText(properties.getApiKey());
        boolean hasProject = StringUtils.hasText(properties.getProjectId());
        boolean hasLocation = StringUtils.hasText(properties.getLocation());
        boolean hasVertexConfig = hasProject && hasLocation;
        // Ambiguity Guard: Professional logging
        if (hasApiKey && hasVertexConfig) {
            if (properties.isVertexAi()) {
                logger.info("Both API Key and Vertex AI config detected. Vertex AI mode is explicitly enabled; the API key will be ignored.");
            } else {
                logger.warn("Both API Key and Vertex AI config detected. Defaulting to Gemini Developer API (API Key). " + "To use Vertex AI instead, set 'spring.ai.google.genai.vertex-ai=true'.");
            }
        }
        // Mode Selection with Fail-Fast Validation
        if (properties.isVertexAi()) {
            if (!hasVertexConfig) {
                throw new IllegalStateException("Vertex AI mode requires both 'project-id' and 'location' to be configured.");
            }
            configureVertexAi(builder, properties);
        } else if (hasApiKey) {
            builder.apiKey(properties.getApiKey());
        } else if (hasVertexConfig) {
            logger.debug("Project ID and Location detected. Defaulting to Vertex AI mode.");
            configureVertexAi(builder, properties);
        } else {
            throw new IllegalStateException("Incomplete Google GenAI configuration: Provide 'api-key' for Gemini API " + "or 'project-id' and 'location' for Vertex AI.");
        }
        return builder.build();
    }

    private boolean isVertexAiConfiguration(GoogleGenAiConnectionProperties props) {
        return props.isVertexAi() || (StringUtils.hasText(props.getProjectId()) && StringUtils.hasText(props.getLocation()));
    }

    private void configureVertexAi(Client.Builder builder, GoogleGenAiConnectionProperties props) throws IOException {
        Assert.hasText(props.getProjectId(), "Google GenAI project-id must be set for Vertex AI mode!");
        Assert.hasText(props.getLocation(), "Google GenAI location must be set for Vertex AI mode!");
        builder.project(props.getProjectId()).location(props.getLocation()).vertexAI(true);
        if (props.getCredentialsUri() != null) {
            try (var is = props.getCredentialsUri().getInputStream()) {
                builder.credentials(GoogleCredentials.fromStream(is));
            }
        }
    }

    @Bean
    @ConditionalOnMissingBean
    public GoogleGenAiChatModel googleGenAiChatModel(Client googleGenAiClient, GoogleGenAiChatProperties chatProperties, ToolCallingManager toolCallingManager, ApplicationContext context, ObjectProvider<RetryTemplate> retryTemplate, ObjectProvider<ObservationRegistry> observationRegistry, ObjectProvider<ChatModelObservationConvention> observationConvention, ObjectProvider<ToolExecutionEligibilityPredicate> toolExecutionEligibilityPredicate) {
        GoogleGenAiChatModel chatModel = GoogleGenAiChatModel.builder().genAiClient(googleGenAiClient).defaultOptions(chatProperties.getOptions()).toolCallingManager(toolCallingManager).toolExecutionEligibilityPredicate(toolExecutionEligibilityPredicate.getIfUnique(() -> new DefaultToolExecutionEligibilityPredicate())).retryTemplate(retryTemplate.getIfUnique(() -> RetryUtils.DEFAULT_RETRY_TEMPLATE)).observationRegistry(observationRegistry.getIfUnique(() -> ObservationRegistry.NOOP)).build();
        observationConvention.ifAvailable(chatModel::setObservationConvention);
        return chatModel;
    }

    @Bean
    @ConditionalOnBean(GoogleGenAiChatModel.class)
    @ConditionalOnMissingBean
    @Conditional(CachedContentServiceCondition.class)
    @ConditionalOnProperty(prefix = "spring.ai.google.genai.chat", name = "enable-cached-content", havingValue = "true", matchIfMissing = true)
    public GoogleGenAiCachedContentService googleGenAiCachedContentService(GoogleGenAiChatModel chatModel) {
        // Extract the cached content service from the chat model
