        Content contextContent = Content.builder().parts(Part.builder().text("Additional context here.").build()).build();
        CachedContentRequest request = CachedContentRequest.builder().model(model).displayName(displayName).systemInstruction(systemContent).addContent(contextContent).ttl(ttl).build();
