 *
 * @author Dan Dobrin
 */
@SpringBootTest
@EnabledIfEnvironmentVariable(named = "GOOGLE_API_KEY", matches = ".+")
class GoogleGenAiChatModelMLDevIT {

    private static final Logger logger = LoggerFactory.getLogger(GoogleGenAiChatModelMLDevIT.class);

    @Autowired
    private GoogleGenAiChatModel chatModel;

    @Test
    @SuppressWarnings("unchecked")
    void googleSearchWithServerSideToolInvocations() {
        Prompt prompt = new Prompt(new UserMessage("What are the top 3 most famous pirates in history? Use Google Search."), GoogleGenAiChatOptions.builder().model(ChatModel.GEMINI_2_0_FLASH).googleSearchRetrieval(true).includeServerSideToolInvocations(false).build());
        ChatResponse response = this.chatModel.call(prompt);
        logger.info("Response: {}", response.getResult().getOutput().getText());
        assertThat(response.getResult().getOutput().getText()).isNotEmpty();
    }

    @Test
    @SuppressWarnings("unchecked")
    void googleSearchWithServerSideToolInvocationsGemini3x() {
        Prompt prompt = new Prompt(new UserMessage("What are the top 3 most famous pirates in history? Use Google Search."), GoogleGenAiChatOptions.builder().model(ChatModel.GEMINI_3_PRO_PREVIEW).googleSearchRetrieval(true).includeServerSideToolInvocations(true).build());
        ChatResponse response = this.chatModel.call(prompt);
        logger.info("Response: {}", response.getResult().getOutput().getText());
        assertThat(response.getResult().getOutput().getText()).isNotEmpty();
        Map<String, Object> metadata = response.getResult().getOutput().getMetadata();
        assertThat(metadata).containsKey("serverSideToolInvocations");
        List<Map<String, Object>> invocations = (List<Map<String, Object>>) metadata.get("serverSideToolInvocations");
        assertThat(invocations).isNotEmpty();
        assertThat(invocations).anyMatch(inv -> "toolCall".equals(inv.get("type")));
        assertThat(invocations).anyMatch(inv -> "toolResponse".equals(inv.get("type")));
    }

    @Test
    @SuppressWarnings("unchecked")
    void functionCallingWithGoogleSearchAndServerSideToolInvocations() {
        var promptOptions = GoogleGenAiChatOptions.builder().model(ChatModel.GEMINI_2_5_FLASH).googleSearchRetrieval(false).includeServerSideToolInvocations(false).toolCallbacks(List.of(FunctionToolCallback.builder("get_current_weather", new MockWeatherService()).description("Get the current weather in a given location").inputType(MockWeatherService.Request.class).build())).build();
        Prompt prompt = new Prompt(new UserMessage("What's the weather like in San Francisco? Return the temperature in Celsius. Also, search online for the latest news about San Francisco."), promptOptions);
