@EnabledIfEnvironmentVariable(named = "OPENAI_API_KEY", matches = ".*")
public class OpenAiFunctionCallbackIT {

    private final Logger logger = LoggerFactory.getLogger(OpenAiFunctionCallbackIT.class);

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.openai.apiKey=" + System.getenv("OPENAI_API_KEY"), "spring.ai.openai.chat.options.model=" + "gpt-4o-mini").withConfiguration(AutoConfigurations.of(OpenAiChatAutoConfiguration.class, org.springframework.ai.model.tool.autoconfigure.ToolCallingAutoConfiguration.class)).withUserConfiguration(Config.class);

    @Test
    void functionCallTest() {
        this.contextRunner.withPropertyValues("spring.ai.openai.chat.options.temperature=0.1").run(context -> {
            OpenAiChatModel chatModel = context.getBean(OpenAiChatModel.class);
            UserMessage userMessage = new UserMessage("What's the weather like in San Francisco, Tokyo, and Paris? Please use the provided tools to get the weather for all 3 cities.");
            ChatResponse response = chatModel.call(new Prompt(List.of(userMessage), OpenAiChatOptions.builder().toolNames("WeatherInfo").build()));
            logger.info("Response: {}", response);
            assertThat(response.getResult().getOutput().getText()).contains("30", "10", "15");
        });
    }

    @Test
    void streamFunctionCallTest() {
        this.contextRunner.withPropertyValues("spring.ai.openai.chat.options.temperature=0.1").run(context -> {
            OpenAiChatModel chatModel = context.getBean(OpenAiChatModel.class);
            UserMessage userMessage = new UserMessage("What's the weather like in San Francisco, Tokyo, and Paris? Please use the provided tools to get the weather for all 3 cities. You can call the following functions 'WeatherInfo'");
            Flux<ChatResponse> response = chatModel.stream(new Prompt(List.of(userMessage), OpenAiChatOptions.builder().toolNames("WeatherInfo").build()));
            String content = response.collectList().block().stream().map(ChatResponse::getResults).flatMap(List::stream).map(Generation::getOutput).map(AssistantMessage::getText).collect(Collectors.joining());
            logger.info("Response: {}", content);
            assertThat(content).containsAnyOf("30.0", "30");
            assertThat(content).containsAnyOf("10.0", "10");
            assertThat(content).containsAnyOf("15.0", "15");
        });
    }

    @Configuration
    static class Config {

        @Bean
        public ToolCallback weatherFunctionInfo() {
            return FunctionToolCallback.builder("WeatherInfo", new MockWeatherService()).description("Get the weather in location").inputType(MockWeatherService.Request.class).build();
        }
    }
}

