    @Autowired
    ChatClient chatClient;

    @ParameterizedTest(name = "{0} : {displayName} ")
    @ValueSource(strings = { "paymentStatus", "paymentStatuses" })
    public void transactionPaymentStatuses(String functionName) {
        List<TransactionStatusResponse> content = this.chatClient.prompt().advisors(new SimpleLoggerAdvisor()).toolNames(functionName).user("""
            What is the status of my payment transactions 001, 002 and 003?
            """).call().entity(new ParameterizedTypeReference<List<TransactionStatusResponse>>() {
        });
        logger.info("" + content);
        assertThat(content.get(0).id()).isEqualTo("001");
        assertThat(content.get(0).status()).isEqualTo("pending");
        assertThat(content.get(1).id()).isEqualTo("002");
        assertThat(content.get(1).status()).isEqualTo("approved");
        assertThat(content.get(2).id()).isEqualTo("003");
        assertThat(content.get(2).status()).isEqualTo("rejected");
    }

    @ParameterizedTest(name = "{0} : {displayName} ")
    @ValueSource(strings = { "paymentStatus", "paymentStatuses" })
    public void streamingPaymentStatuses(String functionName) {
        var converter = new BeanOutputConverter<>(new ParameterizedTypeReference<List<TransactionStatusResponse>>() {
        });
        Flux<String> flux = this.chatClient.prompt().advisors(new SimpleLoggerAdvisor()).toolNames(functionName).user(u -> u.text("""
            What is the status of my payment transactions 001, 002 and 003?

            {format}
            """).param("format", converter.getFormat())).stream().content();
        String content = flux.collectList().block().stream().collect(Collectors.joining());
        List<TransactionStatusResponse> structure = converter.convert(content);
        logger.info("" + content);
        assertThat(structure.get(0).id()).isEqualTo("001");
        assertThat(structure.get(0).status()).isEqualTo("pending");
        assertThat(structure.get(1).id()).isEqualTo("002");
        assertThat(structure.get(1).status()).isEqualTo("approved");
        assertThat(structure.get(2).id()).isEqualTo("003");
        assertThat(structure.get(2).status()).isEqualTo("rejected");
    }

    record TransactionStatusResponse(String id, String status) {
    }

    record Transaction(String id) {
    }

    record Status(String name) {
    }

    record Transactions(List<Transaction> transactions) {
    }

    record Statuses(List<Status> statuses) {
    }

    @SpringBootConfiguration
    public static class TestConfiguration {

        @Bean
        @Description("Get the status of a single payment transaction")
        public Function<Transaction, Status> paymentStatus() {
            return transaction -> {
                logger.info("Single transaction: " + transaction);
                return DATASET.get(transaction);
            };
        }

        @Bean
        @Description("Get the list statuses of a list of payment transactions")
        public Function<Transactions, Statuses> paymentStatuses() {
            return transactions -> {
                logger.info("List of transactions: " + transactions);
                return new Statuses(transactions.transactions().stream().map(t -> DATASET.get(t)).toList());
            };
        }

        @Bean
        public ChatClient chatClient(OpenAiChatModel chatModel) {
            return ChatClient.builder(chatModel).build();
        }

        @Bean
        public OpenAiChatModel openAiClient(ToolCallingManager toolCallingManager) {
            return OpenAiChatModel.builder().options(OpenAiChatOptions.builder().apiKey(System.getenv("OPENAI_API_KEY")).model("gpt-4o-mini").temperature(0.1).build()).toolCallingManager(toolCallingManager).build();
        }

        @Bean
        @ConditionalOnMissingBean
        ToolCallbackResolver toolCallbackResolver(GenericApplicationContext applicationContext, List<ToolCallback> toolCallback, List<ToolCallbackProvider> tcbProviders) {
            List<ToolCallback> allFunctionAndToolCallbacks = new ArrayList<>(toolCallback);
            tcbProviders.stream().map(pr -> List.of(pr.getToolCallbacks())).forEach(allFunctionAndToolCallbacks::addAll);
            var staticToolCallbackResolver = new StaticToolCallbackResolver(allFunctionAndToolCallbacks);
            var springBeanToolCallbackResolver = SpringBeanToolCallbackResolver.builder().applicationContext(applicationContext).build();
            return new DelegatingToolCallbackResolver(List.of(staticToolCallbackResolver, springBeanToolCallbackResolver));
        }

        @Bean
        @ConditionalOnMissingBean
        ToolExecutionExceptionProcessor toolExecutionExceptionProcessor() {
            return new DefaultToolExecutionExceptionProcessor(false);
        }

        @Bean
        @ConditionalOnMissingBean
        ToolCallingManager toolCallingManager(ToolCallbackResolver toolCallbackResolver, ToolExecutionExceptionProcessor toolExecutionExceptionProcessor, ObjectProvider<ObservationRegistry> observationRegistry) {
            return ToolCallingManager.builder().observationRegistry(observationRegistry.getIfUnique(() -> ObservationRegistry.NOOP)).toolCallbackResolver(toolCallbackResolver).toolExecutionExceptionProcessor(toolExecutionExceptionProcessor).build();
        }
    }
}

