    @Autowired
    ChatModel chatModel;

    private static final DeepSeekApi.FunctionTool FUNCTION_TOOL = new DeepSeekApi.FunctionTool(DeepSeekApi.FunctionTool.Type.FUNCTION, new DeepSeekApi.FunctionTool.Function("Get the weather in location. Return temperature in 30°F or 30°C format.", "getCurrentWeather", """
        {
        	"type": "object",
        	"properties": {
        		"location": {
        			"type": "string",
        			"description": "The city and state e.g. San Francisco, CA"
        		},
        		"lat": {
        			"type": "number",
        			"description": "The city latitude"
        		},
        		"lon": {
        			"type": "number",
        			"description": "The city longitude"
        		},
        		"unit": {
        			"type": "string",
        			"enum": ["C", "F"]
        		}
        	},
        	"required": ["location", "lat", "lon", "unit"]
        }
        """));

    @Test
    void functionCallTest() {
        UserMessage userMessage = new UserMessage("What's the weather like in San Francisco, Tokyo, and Paris? Return the temperature in Celsius.");
        List<Message> messages = new ArrayList<>(List.of(userMessage));
        var promptOptions = DeepSeekChatOptions.builder().model(DeepSeekApi.ChatModel.DEEPSEEK_CHAT.getValue()).toolCallbacks(List.of(FunctionToolCallback.builder("getCurrentWeather", new MockWeatherService()).description("Get the weather in location").inputType(MockWeatherService.Request.class).build())).build();
        ChatResponse response = this.chatModel.call(new Prompt(messages, promptOptions));
        logger.info("Response: {}", response);
        assertThat(response.getResult().getOutput().getText()).contains("30", "10", "15");
    }

    @Test
    void streamFunctionCallTest() {
        UserMessage userMessage = new UserMessage("What's the weather like in San Francisco, Tokyo, and Paris? Return the temperature in Celsius.");
        List<Message> messages = new ArrayList<>(List.of(userMessage));
        var promptOptions = DeepSeekChatOptions.builder().toolCallbacks(List.of(FunctionToolCallback.builder("getCurrentWeather", new MockWeatherService()).description("Get the weather in location").inputType(MockWeatherService.Request.class).build())).build();
        Flux<ChatResponse> response = this.chatModel.stream(new Prompt(messages, promptOptions));
        String content = response.collectList().block().stream().map(ChatResponse::getResults).flatMap(List::stream).map(Generation::getOutput).map(AssistantMessage::getText).filter(Objects::nonNull).collect(Collectors.joining());
        logger.info("Response: {}", content);
        assertThat(content).contains("30", "10", "15");
    }

    @Test
    public void toolFunctionCallWithUsage() {
        var promptOptions = DeepSeekChatOptions.builder().model(DeepSeekApi.ChatModel.DEEPSEEK_CHAT.getValue()).tools(Arrays.asList(FUNCTION_TOOL)).toolCallbacks(List.of(FunctionToolCallback.builder("getCurrentWeather", new MockWeatherService()).description("Get the weather in location").inputType(MockWeatherService.Request.class).build())).build();
        Prompt prompt = new Prompt("What's the weather like in San Francisco? Return the temperature in Celsius.", promptOptions);
        ChatResponse chatResponse = this.chatModel.call(prompt);
        assertThat(chatResponse).isNotNull();
        assertThat(chatResponse.getResult().getOutput()).isNotNull();
        assertThat(chatResponse.getResult().getOutput().getText()).contains("San Francisco");
        assertThat(chatResponse.getResult().getOutput().getText()).contains("30");
        assertThat(chatResponse.getMetadata().getUsage()).isNotNull();
    }

    @Test
    public void testStreamFunctionCallUsage() {
        var promptOptions = DeepSeekChatOptions.builder().model(DeepSeekApi.ChatModel.DEEPSEEK_CHAT.getValue()).tools(Arrays.asList(FUNCTION_TOOL)).toolCallbacks(List.of(FunctionToolCallback.builder("getCurrentWeather", new MockWeatherService()).description("Get the weather in location").inputType(MockWeatherService.Request.class).build())).build();
        Prompt prompt = new Prompt("What's the weather like in San Francisco? Return the temperature in Celsius.", promptOptions);
        ChatResponse chatResponse = this.chatModel.stream(prompt).blockLast();
        assertThat(chatResponse).isNotNull();
        assertThat(chatResponse.getMetadata()).isNotNull();
        assertThat(chatResponse.getMetadata().getUsage()).isNotNull();
    }
}
