        SystemPromptTemplate systemPromptTemplate = new SystemPromptTemplate(this.systemResource);
        Message systemMessage = systemPromptTemplate.createMessage(Map.of("name", "Bob", "voice", "pirate"));
        Prompt prompt = new Prompt(List.of(userMessage, systemMessage));
        ChatResponse response = this.chatModel.call(prompt);
        assertThat(response.getResults()).hasSize(1);
        assertThat(response.getResults().get(0).getOutput().getText()).contains("Blackbeard");
        // needs fine tuning... evaluateQuestionAndAnswer(request, response, false);
    }

    @Test
    void testMessageHistory() {
        UserMessage userMessage = new UserMessage("Tell me about 3 famous pirates from the Golden Age of Piracy and why they did.");
        SystemPromptTemplate systemPromptTemplate = new SystemPromptTemplate(this.systemResource);
        Message systemMessage = systemPromptTemplate.createMessage(Map.of("name", "Bob", "voice", "pirate"));
        Prompt prompt = new Prompt(List.of(userMessage, systemMessage));
        ChatResponse response = this.chatModel.call(prompt);
        assertThat(response.getResult().getOutput().getText()).containsAnyOf("Blackbeard", "Bartholomew");
        var promptWithMessageHistory = new Prompt(List.of(new UserMessage("Dummy"), response.getResult().getOutput(), new UserMessage("Repeat the last assistant message.")));
        response = this.chatModel.call(promptWithMessageHistory);
        assertThat(response.getResult().getOutput().getText()).containsAnyOf("Blackbeard", "Bartholomew");
    }

    @Test
    void streamCompletenessTest() throws InterruptedException {
        UserMessage userMessage = new UserMessage("List ALL natural numbers in range [1, 100]. Make sure to not omit any. Print the full list here, one after another.");
        Prompt prompt = new Prompt(List.of(userMessage));
        StringBuilder answer = new StringBuilder();
        CountDownLatch latch = new CountDownLatch(1);
        Flux<ChatResponse> chatResponseFlux = this.chatModel.stream(prompt).doOnNext(chatResponse -> {
            if (!chatResponse.getResults().isEmpty()) {
                String responseContent = chatResponse.getResults().get(0).getOutput().getText();
                answer.append(responseContent);
            }
        }).doOnComplete(() -> {
            logger.info(answer.toString());
            latch.countDown();
