    private MistralAiApi mistralAiApi;

    private MistralAiChatModel chatModel;

    private MistralAiEmbeddingModel embeddingModel;

    @BeforeEach
    public void beforeEach() {
        this.retryTemplate = RetryUtils.SHORT_RETRY_TEMPLATE;
        this.retryListener = new TestRetryListener();
        this.retryTemplate.setRetryListener(this.retryListener);
        this.chatModel = MistralAiChatModel.builder().mistralAiApi(this.mistralAiApi).defaultOptions(MistralAiChatOptions.builder().temperature(0.7).topP(1.0).safePrompt(false).model(MistralAiApi.ChatModel.MISTRAL_SMALL.getValue()).build()).retryTemplate(this.retryTemplate).build();
        this.embeddingModel = MistralAiEmbeddingModel.builder().mistralAiApi(this.mistralAiApi).retryTemplate(this.retryTemplate).build();
    }

    @Test
    public void mistralAiChatTransientError() {
        var choice = new ChatCompletion.Choice(0, new ChatCompletionMessage("Response", Role.ASSISTANT), ChatCompletionFinishReason.STOP, null);
        ChatCompletion expectedChatCompletion = new ChatCompletion("id", "chat.completion", 789L, "model", List.of(choice), new MistralAiApi.Usage(10, 10, 10));
        given(this.mistralAiApi.chatCompletionEntity(isA(ChatCompletionRequest.class))).willThrow(new TransientAiException("Transient Error 1")).willThrow(new TransientAiException("Transient Error 2")).willReturn(ResponseEntity.of(Optional.of(expectedChatCompletion)));
        var result = this.chatModel.call(new Prompt("text"));
        assertThat(result).isNotNull();
        assertThat(result.getResult().getOutput().getText()).isSameAs("Response");
        assertThat(this.retryListener.onSuccessRetryCount).isEqualTo(1);
        assertThat(this.retryListener.onErrorRetryCount).isEqualTo(2);
    }

    @Test
    public void mistralAiChatNonTransientError() {
        given(this.mistralAiApi.chatCompletionEntity(isA(ChatCompletionRequest.class))).willThrow(new RuntimeException("Non Transient Error"));
        assertThrows(RuntimeException.class, () -> this.chatModel.call(new Prompt("text")));
    }

    @Test
    @Disabled("Currently stream() does not implement retry")
    public void mistralAiChatStreamTransientError() {
        var choice = new ChatCompletionChunk.ChunkChoice(0, new ChatCompletionMessage("Response", Role.ASSISTANT), ChatCompletionFinishReason.STOP, null);
        ChatCompletionChunk expectedChatCompletion = new ChatCompletionChunk("id", "chat.completion.chunk", 789L, "model", List.of(choice), null);
        given(this.mistralAiApi.chatCompletionStream(isA(ChatCompletionRequest.class))).willThrow(new TransientAiException("Transient Error 1")).willThrow(new TransientAiException("Transient Error 2")).willReturn(Flux.just(expectedChatCompletion));
        var result = this.chatModel.stream(new Prompt("text"));
        assertThat(result).isNotNull();
        assertThat(result.collectList().block().get(0).getResult().getOutput().getText()).isSameAs("Response");
        assertThat(this.retryListener.onSuccessRetryCount).isEqualTo(1);
        assertThat(this.retryListener.onErrorRetryCount).isEqualTo(2);
    }

    @Test
    @Disabled("Currently stream() does not implement retry")
    public void mistralAiChatStreamNonTransientError() {
        given(this.mistralAiApi.chatCompletionStream(isA(ChatCompletionRequest.class))).willThrow(new RuntimeException("Non Transient Error"));
        assertThrows(RuntimeException.class, () -> this.chatModel.stream(new Prompt("text")));
    }

    @Test
    public void mistralAiEmbeddingTransientError() {
        EmbeddingList<Embedding> expectedEmbeddings = new EmbeddingList<>("list", List.of(new Embedding(0, new float[] { 9.9f, 8.8f })), "model", new MistralAiApi.Usage(10, 10, 10));
        given(this.mistralAiApi.embeddings(isA(EmbeddingRequest.class))).willThrow(new TransientAiException("Transient Error 1")).willThrow(new TransientAiException("Transient Error 2")).willReturn(ResponseEntity.of(Optional.of(expectedEmbeddings)));
        var result = this.embeddingModel.call(new org.springframework.ai.embedding.EmbeddingRequest(List.of("text1", "text2"), null));
        assertThat(result).isNotNull();
        assertThat(result.getResult().getOutput()).isEqualTo(new float[] { 9.9f, 8.8f });
        assertThat(this.retryListener.onSuccessRetryCount).isEqualTo(1);
        assertThat(this.retryListener.onErrorRetryCount).isEqualTo(2);
    }

    @Test
    public void mistralAiEmbeddingNonTransientError() {
        given(this.mistralAiApi.embeddings(isA(EmbeddingRequest.class))).willThrow(new RuntimeException("Non Transient Error"));
        assertThrows(RuntimeException.class, () -> this.embeddingModel.call(new org.springframework.ai.embedding.EmbeddingRequest(List.of("text1", "text2"), null)));
    }

    @Test
    public void mistralAiChatMixedTransientAndNonTransientErrors() {
        given(this.mistralAiApi.chatCompletionEntity(isA(ChatCompletionRequest.class))).willThrow(new TransientAiException("Transient Error")).willThrow(new RuntimeException("Non Transient Error"));
        // Should fail immediately on non-transient error, no further retries
        assertThrows(RuntimeException.class, () -> this.chatModel.call(new Prompt("text")));
        // Should have 1 retry attempt before hitting non-transient error
        assertThat(this.retryListener.onErrorRetryCount).isEqualTo(1);
    }

    private static class TestRetryListener implements RetryListener {

        int onErrorRetryCount = 0;

        int onSuccessRetryCount = 0;

        @Override
        public void beforeRetry(final RetryPolicy retryPolicy, final Retryable<?> retryable) {
            // Count each retry attempt
            this.onErrorRetryCount++;
        }

        @Override
        public void onRetrySuccess(final RetryPolicy retryPolicy, final Retryable<?> retryable, final Object result) {
            // Count successful retries - we increment when we succeed after a failure
            this.onSuccessRetryCount++;
        }
    }
}

