/**
 * AWS OpenSearch configuration.
 * <p>
 * This configuration is only enabled if AWS SDK classes are present on the classpath
 * <b>and</b> the property {@code spring.ai.vectorstore.opensearch.aws.enabled} is set
 * to {@code true} (default: true).
 * <p>
 * Set {@code spring.ai.vectorstore.opensearch.aws.enabled=false} to disable
 * AWS-specific OpenSearch configuration when AWS SDK is present for other services
 * (e.g., S3).
 */
@Configuration(proxyBeanMethods = false)
@ConditionalOnClass({ AwsCredentialsProvider.class, Region.class, ApacheHttpClient.class })
@ConditionalOnProperty(name = "spring.ai.vectorstore.opensearch.aws.enabled", havingValue = "true", matchIfMissing = true)
static class AwsOpenSearchConfiguration {

    @Bean
    @ConditionalOnMissingBean(AwsOpenSearchConnectionDetails.class)
    PropertiesAwsOpenSearchConnectionDetails awsOpenSearchConnectionDetails(OpenSearchVectorStoreProperties properties) {
        return new PropertiesAwsOpenSearchConnectionDetails(properties);
    }

    @Bean
    @ConditionalOnMissingBean
    OpenSearchClient openSearchClient(OpenSearchVectorStoreProperties properties, Optional<SslBundles> sslBundles, AwsOpenSearchConnectionDetails connectionDetails, AwsSdk2TransportOptions options) {
        Region region = Region.of(connectionDetails.getRegion());
        var httpClientBuilder = ApacheHttpClient.builder();
        Optional.ofNullable(properties.getConnectionTimeout()).ifPresent(httpClientBuilder::connectionTimeout);
        Optional.ofNullable(properties.getReadTimeout()).ifPresent(httpClientBuilder::socketTimeout);
        if (sslBundles.isPresent()) {
            Optional.ofNullable(properties.getSslBundle()).map(bundle -> sslBundles.get().getBundle(bundle)).ifPresent(bundle -> httpClientBuilder.tlsKeyManagersProvider(() -> bundle.getManagers().getKeyManagers()).tlsTrustManagersProvider(() -> bundle.getManagers().getTrustManagers()));
        }
        OpenSearchTransport transport = new AwsSdk2Transport(httpClientBuilder.build(), Objects.requireNonNull(connectionDetails.getHost(properties.getAws().getDomainName()), "hostname is required"), Objects.requireNonNull(properties.getAws().getServiceName(), "serviceName is required"), region, options);
        return new OpenSearchClient(transport);
    }

    @Bean
    @ConditionalOnMissingBean
    AwsSdk2TransportOptions options(AwsOpenSearchConnectionDetails connectionDetails) {
        return AwsSdk2TransportOptions.builder().setCredentials(StaticCredentialsProvider.create(AwsBasicCredentials.create(connectionDetails.getAccessKey(), connectionDetails.getSecretKey()))).build();
    }
}

