     */
    @JsonIgnore
    private ContentFormatter contentFormatter = DEFAULT_CONTENT_FORMATTER;

    @JsonCreator(mode = JsonCreator.Mode.PROPERTIES)
    public Document(@JsonProperty("content") @Nullable String content) {
        this(content, new HashMap<>());
