    void callShouldThrowOnError() {
        when(this.tool.name()).thenReturn("testTool");
        var callToolResult = McpSchema.CallToolResult.builder().addTextContent("Some error data").isError(true).build();
        when(this.mcpClient.callTool(any(McpSchema.CallToolRequest.class))).thenReturn(Mono.just(callToolResult));
        var callback = AsyncMcpToolCallback.builder().mcpClient(this.mcpClient).tool(this.tool).prefixedToolName(this.tool.name()).build();
        assertThatThrownBy(() -> callback.call("{\"param\":\"value\"}")).isInstanceOf(ToolExecutionException.class).cause().isInstanceOf(IllegalStateException.class).hasMessage("Error calling tool: [TextContent[annotations=null, text=Some error data, meta=null]]");
    }

    @Test
    void callShouldWrapReactiveErrors() {
        when(this.tool.name()).thenReturn("testTool");
        when(this.mcpClient.callTool(any(McpSchema.CallToolRequest.class))).thenReturn(Mono.error(new Exception("Testing tool error")));
