@AutoConfiguration
@EnableConfigurationProperties(McpServerProperties.class)
@Conditional({ ToolCallbackConverterAutoConfiguration.ToolCallbackConverterCondition.class, McpServerAutoConfiguration.NonStatelessServerCondition.class })
public class ToolCallbackConverterAutoConfiguration {

    @Bean
    @ConditionalOnProperty(prefix = McpServerProperties.CONFIG_PREFIX, name = "type", havingValue = "SYNC", matchIfMissing = true)
    public List<McpServerFeatures.SyncToolSpecification> syncTools(ObjectProvider<List<ToolCallback>> toolCalls, List<ToolCallback> toolCallbackList, ObjectProvider<List<ToolCallbackProvider>> tcbProviderList, ObjectProvider<ToolCallbackProvider> tcbProviders, McpServerProperties serverProperties) {
        List<ToolCallback> tools = ToolCallbackUtils.aggregateToolCallbacks(toolCalls, toolCallbackList, tcbProviderList, tcbProviders, serverProperties.isExposeMcpClientTools());
        return this.toSyncToolSpecifications(tools, serverProperties);
    }

    private List<McpServerFeatures.SyncToolSpecification> toSyncToolSpecifications(List<ToolCallback> tools, McpServerProperties serverProperties) {
        // De-duplicate tools by their name, keeping the first occurrence of each tool
        // name
        return // Key: tool name
        tools.stream().collect(Collectors.toMap(tool -> tool.getToolDefinition().name(), tool -> tool, // On duplicate key, keep the
        (existing, replacement) -> existing)).// existing tool
        values().stream().map(tool -> {
            String toolName = tool.getToolDefinition().name();
            MimeType mimeType = (serverProperties.getToolResponseMimeType().containsKey(toolName)) ? MimeType.valueOf(serverProperties.getToolResponseMimeType().get(toolName)) : null;
            return McpToolUtils.toSyncToolSpecification(tool, mimeType);
        }).toList();
    }

    @Bean
    @ConditionalOnProperty(prefix = McpServerProperties.CONFIG_PREFIX, name = "type", havingValue = "ASYNC")
    public List<McpServerFeatures.AsyncToolSpecification> asyncTools(ObjectProvider<List<ToolCallback>> toolCalls, List<ToolCallback> toolCallbackList, ObjectProvider<List<ToolCallbackProvider>> tcbProviderList, ObjectProvider<ToolCallbackProvider> tcbProviders, McpServerProperties serverProperties) {
        List<ToolCallback> tools = ToolCallbackUtils.aggregateToolCallbacks(toolCalls, toolCallbackList, tcbProviderList, tcbProviders, serverProperties.isExposeMcpClientTools());
        return this.toAsyncToolSpecification(tools, serverProperties);
    }

    private List<McpServerFeatures.AsyncToolSpecification> toAsyncToolSpecification(List<ToolCallback> tools, McpServerProperties serverProperties) {
        // De-duplicate tools by their name, keeping the first occurrence of each tool
        // name
        return // Key: tool name
        tools.stream().collect(Collectors.toMap(tool -> tool.getToolDefinition().name(), tool -> tool, // Value: the tool itself
        (existing, replacement) -> existing)).// existing tool
        values().stream().map(tool -> {
            String toolName = tool.getToolDefinition().name();
            MimeType mimeType = (serverProperties.getToolResponseMimeType().containsKey(toolName)) ? MimeType.valueOf(serverProperties.getToolResponseMimeType().get(toolName)) : null;
            return McpToolUtils.toAsyncToolSpecification(tool, mimeType);
        }).toList();
    }

    private static boolean isMcpToolProvider(ToolCallbackProvider tcbp) {
        return !(tcbp instanceof org.springframework.ai.mcp.SyncMcpToolCallbackProvider) && !(tcbp instanceof org.springframework.ai.mcp.AsyncMcpToolCallbackProvider);
    }

    public static class ToolCallbackConverterCondition extends AllNestedConditions {

        public ToolCallbackConverterCondition() {
            super(ConfigurationPhase.PARSE_CONFIGURATION);
        }

        @ConditionalOnProperty(prefix = McpServerProperties.CONFIG_PREFIX, name = "enabled", havingValue = "true", matchIfMissing = true)
        static class McpServerEnabledCondition {
        }

        @ConditionalOnProperty(prefix = McpServerProperties.CONFIG_PREFIX, name = "tool-callback-converter", havingValue = "true", matchIfMissing = true)
        static class ToolCallbackConvertCondition {
        }
    }
}

