 */
final class ToolCallbackUtils {

    private static final Logger log = LoggerFactory.getLogger(ToolCallbackUtils.class);

    private ToolCallbackUtils() {
    }

    static List<ToolCallback> aggregateToolCallbacks(ObjectProvider<List<ToolCallback>> toolCalls, List<ToolCallback> toolCallbackList, ObjectProvider<List<ToolCallbackProvider>> tcbProviderList, ObjectProvider<ToolCallbackProvider> tcbProviders, boolean includeMcpTools) {
        var allToolCallbacks = Stream.concat(toolCalls.stream().flatMap(List::stream), toolCallbackList.stream()).filter(toolCallback -> includeMcpTools || !isMcpToolCallback(toolCallback));
        var allCallbackProviders = Stream.concat(tcbProviderList.stream().flatMap(List::stream), tcbProviders.stream());
        AtomicBoolean hasExcludedToolProvider = new AtomicBoolean(false);
        var filteredProviders = allCallbackProviders.filter(provider -> {
            var includeProvider = includeMcpTools || !isMcpToolProvider(provider);
            if (!includeProvider) {
                hasExcludedToolProvider.set(true);
            }
            return includeProvider;
        }).distinct();
        var toolCallbacksFromProviders = filteredProviders.map(pr -> List.of(pr.getToolCallbacks())).flatMap(List::stream).filter(Objects::nonNull);
        var toolCallbacks = Stream.concat(allToolCallbacks, toolCallbacksFromProviders).toList();
        // After consuming all the streams, log if we have excluded MCP tools
        if (hasExcludedToolProvider.get()) {
            log.warn("Found MCP Clients. The MCP Client tools will not be exposed by the MCP Server. If you would like to expose the tools, set {}.expose-mcp-client-tools=true.", McpServerProperties.CONFIG_PREFIX);
        }
        return toolCallbacks;
    }

    static boolean isMcpToolCallback(ToolCallback toolCallback) {
        return (toolCallback instanceof SyncMcpToolCallback) || (toolCallback instanceof AsyncMcpToolCallback);
    }

    static boolean isMcpToolProvider(ToolCallbackProvider tcbp) {
        return (tcbp instanceof org.springframework.ai.mcp.SyncMcpToolCallbackProvider) || (tcbp instanceof org.springframework.ai.mcp.AsyncMcpToolCallbackProvider);
    }
}

