        if (this.invalidateCache) {
            this.lock.lock();
            try {
                if (this.invalidateCache) {
                    this.cachedToolCallbacks = this.mcpClients.stream().flatMap(mcpClient -> mcpClient.listTools().tools().stream().filter(tool -> this.toolFilter.test(connectionInfo(mcpClient), tool)).<ToolCallback>map(tool -> SyncMcpToolCallback.builder().mcpClient(mcpClient).tool(tool).prefixedToolName(this.toolNamePrefixGenerator.prefixedToolName(connectionInfo(mcpClient), tool)).toolContextToMcpMetaConverter(this.toolContextToMcpMetaConverter).build())).toList();
                    this.validateToolCallbacks(this.cachedToolCallbacks);
                    this.invalidateCache = false;
                }
            } finally {
                this.lock.unlock();
            }
        }
        return this.cachedToolCallbacks.toArray(new ToolCallback[0]);
    }

