     * @param prefixedToolName the prefixed name for the tool
     * @param tool the MCP tool
     * @return a ToolDefinition with normalized input schema
     */
    public static ToolDefinition createToolDefinition(String prefixedToolName, McpSchema.Tool tool) {
        return DefaultToolDefinition.builder().name(prefixedToolName).description(tool.description()).inputSchema(JsonSchemaUtils.ensureValidInputSchema(ModelOptionsUtils.toJsonString(tool.inputSchema()))).build();
    }

    private static SharedSyncToolSpecification toSharedSyncToolSpecification(ToolCallback toolCallback, @Nullable MimeType mimeType) {
        var tool = McpSchema.Tool.builder().name(toolCallback.getToolDefinition().name()).description(toolCallback.getToolDefinition().description()).inputSchema(ModelOptionsUtils.jsonToObject(toolCallback.getToolDefinition().inputSchema(), McpSchema.JsonSchema.class)).build();
        return new SharedSyncToolSpecification(tool, (exchangeOrContext, request) -> {
            try {
                String callResult = toolCallback.call(ModelOptionsUtils.toJsonString(request.arguments()), new ToolContext(Map.of(TOOL_CONTEXT_MCP_EXCHANGE_KEY, exchangeOrContext)));
                if (mimeType != null && mimeType.toString().startsWith("image")) {
                    McpSchema.Annotations annotations = new McpSchema.Annotations(List.of(Role.ASSISTANT), null);
                    return McpSchema.CallToolResult.builder().content(List.of(new McpSchema.ImageContent(annotations, callResult, mimeType.toString()))).isError(false).build();
                }
                return McpSchema.CallToolResult.builder().content(List.of(new McpSchema.TextContent(callResult))).isError(false).build();
            } catch (Exception e) {
                return McpSchema.CallToolResult.builder().content(List.of(new McpSchema.TextContent(e.getMessage()))).isError(true).build();
            }
        });
    }

