@Testcontainers
@EnabledIfEnvironmentVariable(named = "OPENAI_API_KEY", matches = ".+")
class MongoDBAtlasVectorStoreAutoConfigurationIT {

    @Container
    static MongoDBAtlasLocalContainer mongo = new MongoDBAtlasLocalContainer("mongodb/mongodb-atlas-local:8.0.0");

    private ApplicationContextRunner getContextRunner() {
        return new ApplicationContextRunner().withUserConfiguration(Config.class).withConfiguration(AutoConfigurations.of(MongoAutoConfiguration.class, DataMongoAutoConfiguration.class, MongoDBAtlasVectorStoreAutoConfiguration.class, RestClientAutoConfiguration.class, OpenAiEmbeddingAutoConfiguration.class)).withPropertyValues("spring.ai.vectorstore.mongodb.initialize-schema=true", "spring.ai.vectorstore.mongodb.collection-name=test_collection", "spring.ai.vectorstore.mongodb.index-name=text_index", "spring.ai.openai.api-key=" + System.getenv("OPENAI_API_KEY"));
    }

    List<Document> documents = List.of(new Document("Spring AI rocks!! Spring AI rocks!! Spring AI rocks!! Spring AI rocks!! Spring AI rocks!!", Collections.singletonMap("meta1", "meta1")), new Document("Hello World Hello World Hello World Hello World Hello World Hello World Hello World"), new Document("Great Depression Great Depression Great Depression Great Depression Great Depression Great Depression", Collections.singletonMap("meta2", "meta2")), new Document("Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers", Collections.singletonMap("foo", "bar")), new Document("Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers Testcontainers", Collections.singletonMap("foo", "baz")));

    @Test
    public void addAndSearch() {
        getContextRunner().run(context -> {
            VectorStore vectorStore = context.getBean(VectorStore.class);
            TestObservationRegistry observationRegistry = context.getBean(TestObservationRegistry.class);
            vectorStore.add(this.documents);
            ObservationTestUtil.assertObservationRegistry(observationRegistry, VectorStoreProvider.MONGODB, VectorStoreObservationContext.Operation.ADD);
            observationRegistry.clear();
            // Await a second for the document to be indexed
            Thread.sleep(5000);
            List<Document> results = vectorStore.similaritySearch(SearchRequest.builder().query("Great").topK(1).build());
            assertThat(results).hasSize(1);
            Document resultDoc = results.get(0);
            assertThat(resultDoc.getId()).isEqualTo(this.documents.get(2).getId());
            assertThat(resultDoc.getText()).isEqualTo("Great Depression Great Depression Great Depression Great Depression Great Depression Great Depression");
            assertThat(resultDoc.getMetadata()).containsEntry("meta2", "meta2");
            ObservationTestUtil.assertObservationRegistry(observationRegistry, VectorStoreProvider.MONGODB, VectorStoreObservationContext.Operation.QUERY);
            observationRegistry.clear();
            // Remove all documents from the store
            vectorStore.delete(this.documents.stream().map(Document::getId).collect(Collectors.toList()));
            ObservationTestUtil.assertObservationRegistry(observationRegistry, VectorStoreProvider.MONGODB, VectorStoreObservationContext.Operation.DELETE);
            observationRegistry.clear();
            List<Document> results2 = vectorStore.similaritySearch(SearchRequest.builder().query("Great").topK(1).build());
            assertThat(results2).isEmpty();
            context.getBean(MongoTemplate.class).dropCollection("test_collection");
        });
    }

    @Test
    public void addAndSearchWithFilters() {
        getContextRunner().withPropertyValues("spring.ai.vectorstore.mongodb.metadata-fields-to-filter=foo").run(context -> {
            VectorStore vectorStore = context.getBean(VectorStore.class);
            vectorStore.add(this.documents);
            // Await a second for the document to be indexed
            Thread.sleep(5000);
            List<Document> results = vectorStore.similaritySearch(SearchRequest.builder().query("Testcontainers").topK(2).build());
            assertThat(results).hasSize(2);
            results.forEach(doc -> assertThat(doc.getText().contains("Testcontainers")).isTrue());
            FilterExpressionBuilder b = new FilterExpressionBuilder();
            results = vectorStore.similaritySearch(SearchRequest.builder().query("Testcontainers").topK(2).filterExpression(b.eq("foo", "bar").build()).build());
            assertThat(results).hasSize(1);
            Document resultDoc = results.get(0);
            assertThat(resultDoc.getId()).isEqualTo(this.documents.get(3).getId());
            assertThat(resultDoc.getText().contains("Testcontainers")).isTrue();
            assertThat(resultDoc.getMetadata()).containsEntry("foo", "bar");
            context.getBean(MongoTemplate.class).dropCollection("test_collection");
        });
    }

    @Test
    public void autoConfigurationDisabledWhenTypeIsNone() {
        getContextRunner().withPropertyValues("spring.ai.vectorstore.type=none").run(context -> {
            assertThat(context.getBeansOfType(MongoDBAtlasVectorStoreProperties.class)).isEmpty();
            assertThat(context.getBeansOfType(MongoDBAtlasVectorStore.class)).isEmpty();
            assertThat(context.getBeansOfType(VectorStore.class)).isEmpty();
        });
    }

    @Test
    public void autoConfigurationEnabledByDefault() {
        getContextRunner().run(context -> {
            assertThat(context.getBeansOfType(MongoDBAtlasVectorStoreProperties.class)).isNotEmpty();
            assertThat(context.getBeansOfType(VectorStore.class)).isNotEmpty();
            assertThat(context.getBean(VectorStore.class)).isInstanceOf(MongoDBAtlasVectorStore.class);
        });
    }

    @Test
    public void autoConfigurationEnabledWhenTypeIsMongodbAtlas() {
        getContextRunner().withPropertyValues("spring.ai.vectorstore.type=mongodb-atlas").run(context -> {
            assertThat(context.getBeansOfType(MongoDBAtlasVectorStoreProperties.class)).isNotEmpty();
            assertThat(context.getBeansOfType(VectorStore.class)).isNotEmpty();
            assertThat(context.getBean(VectorStore.class)).isInstanceOf(MongoDBAtlasVectorStore.class);
        });
    }

    @Configuration(proxyBeanMethods = false)
    static class Config {

        @Bean
        public TestObservationRegistry observationRegistry() {
            return TestObservationRegistry.create();
        }

        @Bean
        public MongoConnectionDetails mongoConnectionDetails() {
            return new MongoConnectionDetails() {

                @Override
                public ConnectionString getConnectionString() {
                    // Add database name to the connection string
                    String baseUri = mongo.getConnectionString();
                    String uriWithDb = baseUri.replace("/?", "/springaisample?");
                    return new ConnectionString(uriWithDb);
                }
            };
        }
    }
}

